'use client';

import { MotionNumber } from '@/components/core/motion-number';
import { useDocumentVisible } from '@/registry/ndeko/hooks/use-agent-run';
import { useSession } from '@/registry/ndeko/hooks/use-session';
import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { spokenUnless } from '@/registry/ndeko/lib/demonstration';
import { Badge } from '@/registry/ndeko/ui/badge';
import { LiveRegion } from '@/registry/ndeko/ui/live-region';
import { MeshTile } from '@/registry/ndeko/ui/mesh-tile';
import { ReplayButton } from '@/registry/ndeko/ui/replay-button';

import {
  AGENT_IDS,
  AGENTS,
  MAP_TITLE,
  REGIONS,
  type AgentId,
  type RegionId,
} from './data';
import { MapStage } from './map-stage';
import {
  INITIAL,
  LOOP_AFTER_MS,
  reducer,
  RESTING,
  SCRIPT,
  totalRunsOf,
} from './session';

const SESSION = {
  reducer,
  initial: INITIAL,
  resting: RESTING,
  script: SCRIPT,
  loopAfter: LOOP_AFTER_MS,
};

function liveWordOf(count: number) {
  if (count === 1) {
    return 'run live';
  }
  return 'runs live';
}

function regionsWordOf(count: number) {
  if (count === 1) {
    return '1 region';
  }
  return `${count} regions`;
}

function AgentEntry({ id }: { id: AgentId }) {
  const agent = AGENTS[id];
  const color = seriesColorOf(agent.series);

  return (
    <span className='flex items-center gap-1.5'>
      <MeshTile seed={agent.name} color={color} size='sm' />
      {agent.name}
    </span>
  );
}

/** What the marks of the map mean: a light takes the colour of the agent whose run it carries. */
function Legend() {
  return (
    <ul
      aria-label='Legend'
      className='text-muted-foreground flex flex-wrap items-center gap-x-5 gap-y-2 text-xs'
    >
      <li className='flex items-center gap-1.5'>
        <span
          aria-hidden='true'
          className='bg-primary ring-card size-2.5 rounded-full ring-2'
        />
        Region, larger with more runs
      </li>
      <li className='flex items-center gap-1.5'>
        <span
          aria-hidden='true'
          className='bg-foreground/30 h-px w-4 rounded-full'
        />
        Route
      </li>
      <li className='flex flex-wrap items-center gap-x-3 gap-y-1'>
        <span>Run handed off by</span>
        {AGENT_IDS.map((id) => (
          <AgentEntry key={id} id={id} />
        ))}
      </li>
    </ul>
  );
}

export default function Maps02() {
  const {
    ref,
    isInView,
    isAutoplaying,
    state,
    act,
    pressed,
    isFinished,
    restart,
  } = useSession(SESSION);
  const isVisible = useDocumentVisible();
  const isOnScreen = isInView && isVisible;
  const total = totalRunsOf(state);
  const canReplay = isFinished && !isAutoplaying;
  const message = spokenUnless(isAutoplaying, state.notice);
  const regionsWord = regionsWordOf(REGIONS.length);

  function toggle(id: RegionId) {
    act({ type: 'toggled', id });
  }

  function clear() {
    act({ type: 'cleared' });
  }

  return (
    <div
      ref={ref}
      className='bg-background text-foreground @container min-h-dvh w-full'
    >
      <div className='mx-auto flex max-w-5xl flex-col gap-4 p-4 @3xl:gap-5 @3xl:p-8'>
        <header className='flex flex-wrap items-end gap-x-4 gap-y-3'>
          <div className='flex min-w-0 flex-1 flex-col gap-0.5'>
            <h1 className='text-lg font-semibold text-balance'>{MAP_TITLE}</h1>
            <p className='text-muted-foreground flex flex-wrap items-center gap-x-2 gap-y-1 text-xs'>
              Runs handed off between {regionsWord}
              <Badge variant='secondary'>Illustrative</Badge>
            </p>
          </div>
          <ReplayButton
            isShown={canReplay}
            onReplay={restart}
            label='Replay the map'
          />
          <p className='flex items-baseline gap-1.5'>
            <MotionNumber
              value={total}
              className='text-2xl leading-8 font-semibold'
            />
            <span className='text-muted-foreground text-xs'>
              {liveWordOf(total)}
            </span>
          </p>
        </header>

        <div className='bg-foreground/[0.03] rounded-xl p-3 @2xl:p-6'>
          <MapStage
            runs={state.runs}
            flights={state.flights}
            landings={state.landings}
            selectedId={state.selectedId}
            pressed={pressed}
            isActive={isOnScreen}
            onToggle={toggle}
            onClear={clear}
          />
        </div>

        <Legend />
      </div>
      <LiveRegion message={message} />
    </div>
  );
}

'use client';

import { useEffect, useLayoutEffect, useRef } from 'react';

import { DottedMap } from '@/components/core/dotted-map';
import { MotionNumber } from '@/components/core/motion-number';
import { usePrefersReducedMotion } from '@/registry/ndeko/hooks/use-prefers-reduced-motion';
import { seriesColorOf } from '@/registry/ndeko/lib/agent-run';
import { pressedQuietOf } from '@/registry/ndeko/lib/demonstration';
import { cn } from '@/registry/ndeko/lib/utils';

import {
  AGENTS,
  regionOf,
  REGIONS,
  ROUTES,
  routeBetween,
  touchesRegion,
  type Region,
  type RegionId,
} from './data';
import {
  arcPathOf,
  bendOf,
  pointOf,
  shareOf,
  VIEW_BOX,
  VIEW_WIDTH,
  type MapPoint,
  type Share,
} from './projection';
import { FLIGHT_MS, pinnedLineOf, type Flight } from './session';

/** The first half of a parabola, as an easing: fast away from the chord, slow at the top. */
const RISE = 'cubic-bezier(0.3333, 0.6667, 0.6667, 1)';

/** The second half: slow from the top, fast back onto the chord. */
const FALL = 'cubic-bezier(0.3333, 0, 0.6667, 0.3333)';

/** A marker this close to the top of the map opens its bubble below, inside the map. */
const NEAR_TOP = 0.35;

const DOT_SCALE_MIN = 0.75;

const DOT_SCALE_MAX = 1.35;

const DOT_SCALE_PER_RUN = 0.035;

const ROUTE_LINE =
  'fill-none stroke-[1.25px] transition-[stroke] duration-200 [vector-effect:non-scaling-stroke]';

const MARKER = [
  'group/marker absolute size-6 -translate-x-1/2 -translate-y-1/2 cursor-pointer rounded-full outline-none',
  'transition-[scale,background-color] duration-150 ease-(--ease-out-strong) active:scale-[0.97]',
  'hover:z-10 focus-visible:z-10 data-[pinned=true]:z-10',
  'focus-visible:ring-ring focus-visible:ring-offset-background focus-visible:ring-2 focus-visible:ring-offset-2',
].join(' ');

const DOT =
  'bg-primary size-3 rounded-full transition-[scale,box-shadow] duration-300 ease-(--ease-out-strong)';

const LANDING_RING =
  'ring-primary/60 absolute size-3 scale-[2.6] rounded-full opacity-0 ring-1 transition-[scale,opacity] duration-700 ease-(--ease-out-strong) starting:scale-100 starting:opacity-100';

const BUBBLE = [
  'surface-raised pointer-events-none absolute left-1/2 z-10 w-max max-w-48 rounded-lg px-2 py-1 text-start text-xs leading-4',
  'opacity-0 transition-opacity duration-100',
  'group-hover/marker:opacity-100 group-focus-visible/marker:opacity-100 group-data-[pinned=true]/marker:opacity-100',
].join(' ');

type DrawnRoute = {
  id: string;
  from: RegionId;
  to: RegionId;
  path: string;
};

function placeOf(id: RegionId): MapPoint {
  const region = regionOf(id);
  return pointOf(region.latitude, region.longitude);
}

const DRAWN_ROUTES: DrawnRoute[] = ROUTES.map((route) => {
  const from = placeOf(route.from);
  const to = placeOf(route.to);
  const path = arcPathOf(from, to);
  return { ...route, path };
});

function shareOfRegion(id: RegionId) {
  const point = placeOf(id);
  return shareOf(point);
}

function percentOf(share: number) {
  const percent = share * 100;
  return `${percent}%`;
}

function anchorStyleOf(share: Share) {
  return { left: percentOf(share.left), top: percentOf(share.top) };
}

function clamp(value: number, min: number, max: number) {
  const atLeast = Math.max(value, min);
  return Math.min(atLeast, max);
}

/** A busier region draws a larger dot. */
function dotStyleOf(runs: number) {
  const grown = runs * DOT_SCALE_PER_RUN;
  const raw = DOT_SCALE_MIN + grown;
  const scale = clamp(raw, DOT_SCALE_MIN, DOT_SCALE_MAX);
  return { scale: String(scale) };
}

function dotRingOf(isPinned: boolean) {
  if (isPinned) {
    return 'ring-primary/25 ring-4';
  }
  return 'ring-card ring-2';
}

function routeToneOf(isLit: boolean) {
  if (isLit) {
    return 'stroke-primary/70';
  }
  return 'stroke-foreground/20';
}

function bubblePlaceOf(isNearTop: boolean) {
  if (isNearTop) {
    return 'top-full mt-1';
  }
  return 'bottom-full mb-1';
}

/** The bubble slides from its left edge to its right edge as its marker crosses the map, so it never leaves it. */
function bubbleShiftOf(share: Share) {
  const percent = share.left * 100;
  return { transform: `translateX(-${percent}%)` };
}

function runsNowWordOf(count: number) {
  if (count === 1) {
    return 'run now';
  }
  return 'runs now';
}

type Motion = {
  travel: Keyframe[];
  bend: Keyframe[];
};

/** The bend of the route a flight follows, whichever way it travels it, so the light stays on the drawn line. */
function routeBendOf(flight: Flight) {
  const route = routeBetween(flight.from, flight.to);
  let fromId = flight.from;
  let toId = flight.to;
  if (route) {
    fromId = route.from;
    toId = route.to;
  }
  const from = placeOf(fromId);
  const to = placeOf(toId);
  return bendOf(from, to);
}

/**
 * A quadratic curve is the straight line between its ends plus a parabola away from it. The light
 * travels the line on one element and the parabola on the one inside it, both on transform.
 */
function motionOf(flight: Flight, scale: number): Motion {
  const from = placeOf(flight.from);
  const to = placeOf(flight.to);
  const bend = routeBendOf(flight);
  const spanX = to.x - from.x;
  const spanY = to.y - from.y;
  const dx = spanX * scale;
  const dy = spanY * scale;
  const topX = bend.x * scale;
  const topY = bend.y * scale;
  const travel = [
    { translate: '0px 0px', opacity: 0 },
    { opacity: 1, offset: 0.12 },
    { opacity: 1, offset: 0.86 },
    { translate: `${dx}px ${dy}px`, opacity: 0 },
  ];
  const lift = [
    { translate: '0px 0px', easing: RISE },
    { translate: `${topX}px ${topY}px`, offset: 0.5, easing: FALL },
    { translate: '0px 0px' },
  ];
  return { travel, bend: lift };
}

function RouteLayer({ selectedId }: { selectedId: RegionId | null }) {
  return (
    <svg
      viewBox={VIEW_BOX}
      aria-hidden='true'
      className='pointer-events-none absolute inset-0 size-full overflow-visible'
    >
      {DRAWN_ROUTES.map((route) => {
        const isLit = touchesRegion(route, selectedId);
        return (
          <path
            key={route.id}
            d={route.path}
            className={cn(ROUTE_LINE, routeToneOf(isLit))}
          />
        );
      })}
    </svg>
  );
}

type FlightLightProps = {
  flight: Flight;
  /** False off screen and in a hidden tab: the light waits where it is, as the session does. */
  isActive: boolean;
};

/** One light, once: it leaves when its run departs and fades as the run lands. */
function FlightLight({ flight, isActive }: FlightLightProps) {
  const travelRef = useRef<HTMLSpanElement>(null);
  const bendRef = useRef<HTMLSpanElement>(null);
  const animations = useRef<Animation[]>([]);
  const start = shareOfRegion(flight.from);
  const agent = AGENTS[flight.agentId];
  const color = seriesColorOf(agent.series);
  const dotStyle = { backgroundColor: color };

  useLayoutEffect(() => {
    const travel = travelRef.current;
    const bend = bendRef.current;
    const overlay = travel?.closest<HTMLElement>('[data-map-overlay]');
    const hasElements = travel !== null && bend !== null;
    if (!hasElements || !overlay) {
      return;
    }
    const scale = overlay.clientWidth / VIEW_WIDTH;
    const motion = motionOf(flight, scale);
    const timing: KeyframeAnimationOptions = {
      duration: FLIGHT_MS,
      fill: 'forwards',
    };
    const moving = travel.animate(motion.travel, timing);
    const bending = bend.animate(motion.bend, timing);
    animations.current = [moving, bending];
    return () => {
      moving.cancel();
      bending.cancel();
      animations.current = [];
    };
  }, [flight]);

  /** A finished light is never paused: playing it again would send it back to its start. */
  useEffect(() => {
    for (const animation of animations.current) {
      const isRunning = animation.playState === 'running';
      const isPaused = animation.playState === 'paused';
      const shouldPause = !isActive && isRunning;
      const shouldResume = isActive && isPaused;
      if (shouldPause) {
        animation.pause();
      }
      if (shouldResume) {
        animation.play();
      }
    }
  }, [isActive]);

  return (
    <span
      aria-hidden='true'
      style={anchorStyleOf(start)}
      className='pointer-events-none absolute size-0'
    >
      <span ref={travelRef} className='absolute opacity-0'>
        <span ref={bendRef} className='absolute'>
          <span
            style={dotStyle}
            className='ring-card absolute -top-1 -left-1 size-2 rounded-full ring-2'
          />
        </span>
      </span>
    </span>
  );
}

type RegionMarkerProps = {
  region: Region;
  runs: number;
  isPinned: boolean;
  isPressed: boolean;
  /** The flight that landed here last: a ring answers each new one. */
  landingId: string | undefined;
  onToggle: (id: RegionId) => void;
};

function RegionMarker({
  region,
  runs,
  isPinned,
  isPressed,
  landingId,
  onToggle,
}: RegionMarkerProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const share = shareOfRegion(region.id);
  const isNearTop = share.top < NEAR_TOP;
  const hasLanding = landingId !== undefined;
  const showsRing = hasLanding && !shouldReduceMotion;

  return (
    <span style={anchorStyleOf(share)} className='absolute size-0'>
      <button
        type='button'
        aria-pressed={isPinned}
        aria-label={pinnedLineOf(region.id, runs)}
        data-pinned={isPinned}
        onClick={() => onToggle(region.id)}
        className={cn(MARKER, pressedQuietOf(isPressed))}
      >
        <span
          aria-hidden='true'
          className='absolute inset-0 flex items-center justify-center'
        >
          {showsRing && <span key={landingId} className={LANDING_RING} />}
          <span
            style={dotStyleOf(runs)}
            className={cn(DOT, dotRingOf(isPinned))}
          />
        </span>
        <span
          aria-hidden='true'
          style={bubbleShiftOf(share)}
          className={cn(BUBBLE, bubblePlaceOf(isNearTop))}
        >
          <span className='block font-medium'>
            {region.name}, {region.place}
          </span>
          <span className='text-muted-foreground flex items-baseline gap-1'>
            <MotionNumber value={runs} />
            {runsNowWordOf(runs)}
          </span>
        </span>
      </button>
    </span>
  );
}

export type MapStageProps = {
  runs: Record<RegionId, number>;
  flights: Flight[];
  landings: Partial<Record<RegionId, string>>;
  selectedId: RegionId | null;
  /** The marker a demonstration presses, shown held down. */
  pressed: string | null;
  isActive: boolean;
  onToggle: (id: RegionId) => void;
  onClear: () => void;
};

/**
 * The dotted map with an overlay drawn in its own units: routes as curves, a light along a route for
 * each run handed off, and a button on each region. Under reduced motion the routes stay drawn and
 * still, and no light travels.
 */
export function MapStage({
  runs,
  flights,
  landings,
  selectedId,
  pressed,
  isActive,
  onToggle,
  onClear,
}: MapStageProps) {
  const shouldReduceMotion = usePrefersReducedMotion();
  const showsFlights = !shouldReduceMotion;

  function clearOnEscape(event: React.KeyboardEvent<HTMLDivElement>) {
    const isEscape = event.key === 'Escape';
    const hasPinned = selectedId !== null;
    if (isEscape && hasPinned) {
      onClear();
    }
  }

  return (
    <div className='relative'>
      <DottedMap
        label='World map of live runs'
        dotClassName='text-foreground/15'
      />
      <div
        data-map-overlay
        onKeyDown={clearOnEscape}
        className='absolute inset-0'
      >
        <RouteLayer selectedId={selectedId} />
        {showsFlights &&
          flights.map((flight) => (
            <FlightLight key={flight.id} flight={flight} isActive={isActive} />
          ))}
        {REGIONS.map((region) => (
          <RegionMarker
            key={region.id}
            region={region}
            runs={runs[region.id]}
            isPinned={region.id === selectedId}
            isPressed={pressed === `marker-${region.id}`}
            landingId={landings[region.id]}
            onToggle={onToggle}
          />
        ))}
      </div>
    </div>
  );
}

/**
 * The dotted map is equirectangular: 106 by 40 units over these bounds, drawn in a view box with
 * half a unit of edge. Its overlay places points the same way, so markers sit on the land dots.
 */
const MAP_WIDTH = 106;

const MAP_HEIGHT = 40;

const EDGE = 0.5;

const LONGITUDE_MIN = -180;

const LONGITUDE_SPAN = 360;

const LATITUDE_MAX = 80;

const LATITUDE_SPAN = 136;

const BOTH_EDGES = EDGE * 2;

export const VIEW_WIDTH = MAP_WIDTH + BOTH_EDGES;

const VIEW_HEIGHT = MAP_HEIGHT + BOTH_EDGES;

export const VIEW_BOX = `${-EDGE} ${-EDGE} ${VIEW_WIDTH} ${VIEW_HEIGHT}`;

/** A route bows away from its chord by this share of its length, within these bounds, in map units. */
const BOW_SHARE = 0.15;

const BOW_MIN = 1;

const BOW_MAX = 5;

export type MapPoint = {
  x: number;
  y: number;
};

export type Share = {
  left: number;
  top: number;
};

function clamp(value: number, min: number, max: number) {
  const atLeast = Math.max(value, min);
  return Math.min(atLeast, max);
}

function scaled(point: MapPoint, factor: number): MapPoint {
  const x = point.x * factor;
  const y = point.y * factor;
  return { x, y };
}

function added(first: MapPoint, second: MapPoint): MapPoint {
  const x = first.x + second.x;
  const y = first.y + second.y;
  return { x, y };
}

export function pointOf(latitude: number, longitude: number): MapPoint {
  const fromWest = longitude - LONGITUDE_MIN;
  const fromNorth = LATITUDE_MAX - latitude;
  const westShare = fromWest / LONGITUDE_SPAN;
  const northShare = fromNorth / LATITUDE_SPAN;
  const x = westShare * MAP_WIDTH;
  const y = northShare * MAP_HEIGHT;
  return { x, y };
}

/** Where a point sits in the box of the map, from 0 to 1 on each side. */
export function shareOf(point: MapPoint): Share {
  const fromLeft = point.x + EDGE;
  const fromTop = point.y + EDGE;
  const left = fromLeft / VIEW_WIDTH;
  const top = fromTop / VIEW_HEIGHT;
  return { left, top };
}

function midpointOf(from: MapPoint, to: MapPoint): MapPoint {
  const sum = added(from, to);
  return scaled(sum, 0.5);
}

/** Of the two directions square to a chord, the one that points up the map, so routes bow north. */
function bowDirectionOf(from: MapPoint, to: MapPoint): MapPoint {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const length = Math.hypot(dx, dy);
  const across = { x: dy, y: -dx };
  const first = scaled(across, 1 / length);
  const second = scaled(first, -1);
  if (second.y < first.y) {
    return second;
  }
  return first;
}

/**
 * How far the middle of a route stands from its chord. A quadratic curve reaches half the distance
 * to its control point, so the control point stands twice as far. A light that travels the route
 * either way uses the bend of the route as it is listed, so it follows the drawn curve.
 */
export function bendOf(from: MapPoint, to: MapPoint): MapPoint {
  const dx = to.x - from.x;
  const dy = to.y - from.y;
  const length = Math.hypot(dx, dy);
  const share = length * BOW_SHARE;
  const bow = clamp(share, BOW_MIN, BOW_MAX);
  const direction = bowDirectionOf(from, to);
  return scaled(direction, bow);
}

export function arcPathOf(from: MapPoint, to: MapPoint) {
  const middle = midpointOf(from, to);
  const bend = bendOf(from, to);
  const reach = scaled(bend, 2);
  const control = added(middle, reach);
  return `M ${from.x} ${from.y} Q ${control.x} ${control.y} ${to.x} ${to.y}`;
}

import type { SessionStep } from '@/registry/ndeko/hooks/use-session';

import {
  AGENTS,
  regionOf,
  REGIONS,
  RUNS,
  type AgentId,
  type RegionId,
} from './data';

/** A run on its way from one region to another, drawn as a light along their route. */
export type Flight = {
  id: string;
  agentId: AgentId;
  from: RegionId;
  to: RegionId;
};

export type MapState = {
  /** Runs live in each region. A run in flight belongs to none until it lands. */
  runs: Record<RegionId, number>;
  flights: Flight[];
  /** The last flight that landed in each region: a ring answers it there. */
  landings: Partial<Record<RegionId, string>>;
  /** The marker pinned open, with its routes lit. */
  selectedId: RegionId | null;
  /** The last change, said to screen readers. */
  notice: string;
};

export type MapAction =
  | { type: 'departed'; flight: Flight }
  | { type: 'landed'; id: string }
  | { type: 'started'; region: RegionId }
  | { type: 'finished'; region: RegionId }
  | { type: 'toggled'; id: RegionId }
  | { type: 'cleared' };

type Step = SessionStep<MapState, MapAction>;

/** How long a light takes along its route. The run lands when it arrives. */
export const FLIGHT_MS = 1400;

export const INITIAL: MapState = {
  runs: RUNS,
  flights: [],
  landings: {},
  selectedId: null,
  notice: '',
};

export function runsWordOf(count: number) {
  if (count === 1) {
    return '1 run';
  }
  return `${count} runs`;
}

/** Europe, Frankfurt: 12 runs now. */
export function pinnedLineOf(id: RegionId, runs: number) {
  const region = regionOf(id);
  const count = runsWordOf(runs);
  return `${region.name}, ${region.place}: ${count} now`;
}

export function handoffLineOf(flight: Flight) {
  const agent = AGENTS[flight.agentId].name;
  const from = regionOf(flight.from).name;
  const to = regionOf(flight.to).name;
  return `${agent} handed a run from ${from} to ${to}`;
}

function withRuns(
  runs: Record<RegionId, number>,
  id: RegionId,
  change: number
): Record<RegionId, number> {
  const shifted = runs[id] + change;
  const count = Math.max(0, shifted);
  return { ...runs, [id]: count };
}

function withRegionRuns(
  state: MapState,
  id: RegionId,
  change: number
): MapState {
  const runs = withRuns(state.runs, id, change);
  return { ...state, runs };
}

function departed(state: MapState, flight: Flight): MapState {
  const isFlying = state.flights.some(
    (candidate) => candidate.id === flight.id
  );
  if (isFlying) {
    return state;
  }
  const runs = withRuns(state.runs, flight.from, -1);
  return { ...state, runs, flights: [...state.flights, flight] };
}

function landed(state: MapState, id: string): MapState {
  const flight = state.flights.find((candidate) => candidate.id === id);
  if (!flight) {
    return state;
  }
  const runs = withRuns(state.runs, flight.to, 1);
  const flights = state.flights.filter((candidate) => candidate.id !== id);
  const landings = { ...state.landings, [flight.to]: flight.id };
  const notice = handoffLineOf(flight);
  return { ...state, runs, flights, landings, notice };
}

function toggled(state: MapState, id: RegionId): MapState {
  if (state.selectedId === id) {
    return { ...state, selectedId: null, notice: '' };
  }
  const notice = pinnedLineOf(id, state.runs[id]);
  return { ...state, selectedId: id, notice };
}

export function reducer(state: MapState, action: MapAction): MapState {
  switch (action.type) {
    case 'departed':
      return departed(state, action.flight);
    case 'landed':
      return landed(state, action.id);
    case 'started':
      return withRegionRuns(state, action.region, 1);
    case 'finished':
      return withRegionRuns(state, action.region, -1);
    case 'toggled':
      return toggled(state, action.id);
    case 'cleared':
      return { ...state, selectedId: null, notice: '' };
  }
}

/** Every live run, those in flight included: a hand-off moves a run, it does not end it. */
export function totalRunsOf(state: MapState) {
  let total = state.flights.length;
  for (const region of REGIONS) {
    total += state.runs[region.id];
  }
  return total;
}

function flightOf(
  id: string,
  agentId: AgentId,
  from: RegionId,
  to: RegionId
): Flight {
  return { id, agentId, from, to };
}

function departs(after: number, flight: Flight): Step {
  return { after, action: { type: 'departed', flight } };
}

function lands(after: number, flight: Flight): Step {
  return { after, action: { type: 'landed', id: flight.id } };
}

/** The demonstration pins a marker open, or closes the one it pinned. */
function points(after: number, id: RegionId): Step {
  return {
    after,
    by: 'demo',
    press: `marker-${id}`,
    action: { type: 'toggled', id },
  };
}

